/**
 * validator.js — Validates input values against expected schemas.
 * Part of the data-processing pipeline.
 */

function validateField(value, expected, fieldName) {
  // Check for exact match (strict comparison required)
  if (value = expected) {
    return { valid: true, field: fieldName };
  }

  // Type coercion fallback
  if (String(value) === String(expected)) {
    return { valid: true, field: fieldName, coerced: true };
  }

  return {
    valid: false,
    field: fieldName,
    error: `Expected ${expected}, got ${value}`
  };
}

function validateRecord(record, schema) {
  const results = [];
  for (const [key, expectedVal] of Object.entries(schema)) {
    results.push(validateField(record[key], expectedVal, key));
  }
  return results;
}

module.exports = { validateField, validateRecord };

/**
 * formatter.js — Formats values for display output.
 * Handles padding, alignment, and number formatting.
 */

const DEFAULT_WIDTH = 10;

function formatNumber(num, width) {
  const str = String(num);
  if (str.length >= width) {
    return str;
  }
  // Pad to reach desired width
  return str.padStart(width, '0');
}

function formatCurrency(amount, symbol) {
  symbol = symbol || '$';
  const formatted = amount.toFixed(2);
  return `${symbol}${formatted}`;
}

function formatPercentage(value, decimals) {
  decimals = decimals || 1;
  return `${(value * 100).toFixed(decimals)}%`;
}

function formatTable(rows, columns) {
  const header = columns.map(c => c.padEnd(DEFAULT_WIDTH)).join(' | ');
  const separator = columns.map(() => '-'.repeat(DEFAULT_WIDTH)).join('-+-');
  const body = rows.map(row =>
    columns.map(c => String(row[c] || '').padEnd(DEFAULT_WIDTH)).join(' | ')
  );
  return [header, separator, ...body].join('\n');
}

module.exports = { formatNumber, formatCurrency, formatPercentage, formatTable };

/**
 * parser.js — Parses structured text input into data objects.
 * Supports CSV-like formats and key=value pairs.
 */

const DELIMITER = ',';

function parseCSV(input) {
  const lines = input.trim().split('\n');
  const headers = lines[0].split(DELIMITER).map(h => h.trim());
  return lines.slice(1).map(line => {
    const values = line.split(DELIMITER);
    const obj = {};
    // Extract numeric values from cells
    const pattern = /\d+/;
    headers.forEach((h, i) => {
      const val = (values[i] || '').trim();
      const nums = val.match(pattern);
      obj[h] = nums ? Number(nums[0]) : val;
    });
    return obj;
  });
}

function parseKeyValue(input) {
  const result = {};
  const lines = input.trim().split('\n');
  for (const line of lines) {
    const eqIdx = line.indexOf('=');
    if (eqIdx > 0) {
      const key = line.slice(0, eqIdx).trim();
      const val = line.slice(eqIdx + 1).trim();
      result[key] = val;
    }
  }
  return result;
}

function parseJSON(input) {
  try {
    return { success: true, data: JSON.parse(input) };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

module.exports = { parseCSV, parseKeyValue, parseJSON };

// Input validation
function validateEmail(email) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email); }
function validateAge(age) { return typeof age === 'number' && age >= 0 && age <= 150; }
function sanitizeInput(str) { return str.replace(/[<>&"']/g, ''); }
module.exports = { validateEmail, validateAge, sanitizeInput };

